cat > src/claimOffice.ts <<'EOF'
export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: 'quote';
  items: Item[];
}

export type Step = QuoteStep;

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

export type Result = { premium: number };

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const MAIN_ITEMS: Record<string, { value: number; basePremium: number }> = {
  sword: { value: 1000, basePremium: 100 },
  amulet: { value: 600, basePremium: 60 },
  staff: { value: 800, basePremium: 80 },
  potion: { value: 400, basePremium: 40 },
};

function quotePremium(items: Item[]): number {
  const policyBase = items.reduce((sum, item) => sum + MAIN_ITEMS[item.type].basePremium, 0);
  const premium = policyBase * (1 + FIRST_INSURANCE_SURCHARGE);
  return Math.ceil(premium) + PROCESSING_FEE;
}

export function runScenario(scenario: Scenario): { results: Result[] } {
  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
}
EOF
